SELECT shopwizard.tStkDailyStockState.*
FROM shopwizard.tStkDailyStockState

    AND StockDate = #{pStockDate}
    AND WarehsCode = #{pWarehsCode}
    AND BarCode = #{pBarCode}
    AND StockName = #{pStockName}
    AND OrderName = #{pOrderName}
    AND ShopCode = #{pShopCode}

LIMIT #{pPageOffset}, #{pPageSize}

SELECT COUNT(*)
FROM shopwizard.tStkDailyStockState

    AND StockDate = #{pStockDate}
    AND WarehsCode = #{pWarehsCode}
    AND BarCode = #{pBarCode}
    AND StockName = #{pStockName}
    AND OrderName = #{pOrderName}
    AND ShopCode = #{pShopCode}

SELECT *
FROM shopwizard.tStkDailyStockState
WHERE StockDate = #{pStockDate}
AND OrderName = #{pOrderName}

mapper.insert:
INSERT INTO shopwizard.tStkDailyStockState (
    StockDate, OrderName, WarehsCode, BarCode, StockName, StockCost, BoxQty, CarryQty, EnterQty, ShipQty, ReEnterQty, BrokenQty, BadQty, CorrctQty, StockQty, StockAmt, MakeDate, ExpireDate, AccumBrokenQty, AccumShipQty, StockDesc, ShopCode, State, Remark, RegistId, RegistName, RegistDate, ChangeId, ChangeName, ChangeDate
) VALUES (
    #{stockDate}, #{orderName}, #{warehsCode}, #{barCode}, #{stockName}, #{stockCost}, #{boxQty}, #{carryQty}, #{enterQty}, #{shipQty}, #{reEnterQty}, #{brokenQty}, #{badQty}, #{corrctQty}, #{stockQty}, #{stockAmt}, #{makeDate}, #{expireDate}, #{accumBrokenQty}, #{accumShipQty}, #{stockDesc}, #{shopCode}, #{state}, #{remark}, #{registId}, #{registName}, NOW(), #{changeId}, #{changeName}, NOW()
)

mapper.update:
UPDATE shopwizard.tStkDailyStockState SET
    ShipQty = #{shipQty}, ReEnterQty = #{reEnterQty},
    StockQty = #{stockQty}, StockAmt = #{stockAmt}, StockDesc = #{stockDesc}, State = #{state},
    Remark = #{remark}, ChangeId = #{changeId}, ChangeName = #{changeName}, ChangeDate = NOW()
WHERE StockDate = #{stockDate}
AND OrderName = #{orderName}

UPDATE shopwizard.tStkDailyStockState SET
    CarryQty = CarryQty + #{pDiffQty}, StockQty = StockQty + #{pDiffQty}, StockAmt = StockCost * StockQty,
    ChangeId = #{changeId}, ChangeName = #{changeName}, ChangeDate = NOW()
WHERE StockDate > #{pStockDate}
AND OrderName = #{pOrderName}

mapper.delete:
DELETE FROM shopwizard.tStkDailyStockState
WHERE StockDate = #{stockDate}
AND OrderName = #{orderName}
